INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (1,'Kloster Oetenbach',3546296,'Q1775758','de','47.3744444','8.5411111','Zürich','ZH','Cathedral',0,'["Abgegangenes Bauwerk in Zürich","Christentum in Zürich","Ehemaliger Beginenkonvent in der Schweiz","Ehemaliges Dominikanerinnenkloster in der Schweiz","Ehemaliges Kloster im Kanton Zürich","Geschichte der Religion (Zürich)","Kloster (13. Jahrhundert)","Klöster, die als Gefängnisse genutzt wurden","Zerstört in den 1900er Jahren"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/6/66/Oetenbach_1868.jpg','Photo by Parpan05, Wikimedia Commons','wikipedia-de','This is a drawing of the courtyard of the former Oetenbach Monastery, featuring buildings, a fountain, and people with a horse-drawn cart.',0,135,'2026-01-20T18:43:15.233Z','2026-01-23T21:12:35.345Z','https://upload.wikimedia.org/wikipedia/commons/9/98/Oetenbach_Kreuzgang.jpg','Photo by Parpan05, Wikimedia Commons','This is a black and white engraving of Kloster Oetenbach, showing the building''s exterior through arched openings, with two figures in the foreground.','https://upload.wikimedia.org/wikipedia/commons/b/b5/Oetenbach_Chor.jpg','Photo by Parpan05, Wikimedia Commons','The photo shows the interior of a building with an arched doorway, decorated walls, and a wooden ceiling.',NULL,NULL,NULL,'Das Kloster Oetenbach oder Ötenbach war ein Kloster der Dominikanerinnen in der Stadt Zürich und gehörte zur Diözese Konstanz. Es wurde 1237 erstmals erwähnt, zog um 1285 vom Stadtrand Zürichs in die Stadtmitte und wurde 1525 aufgehoben. Nach der Reformation dienten die Gebäude verschiedenen Zwecken, insbesondere als Zucht- und Waisenhaus.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (2,'Giacometti-Halle',10974169,'Q105171843','de','47.3751970','8.5414230','Zürich','ZH',NULL,0,'["Bildende Kunst (Zürich)","Fresko","Gemälde (20. Jahrhundert)","Giacometti (Familie)","Halle","Umgenutztes Bauwerk im Kanton Zürich","Wandmalerei"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/1/10/Waisenhaus_Zuerich.jpg','Photo by Sidonius, Wikimedia Commons','wikipedia-de','This is a photograph of the Giacometti-Halle, a stone building with a grand entrance and many windows.',0,9,'2026-01-20T18:43:15.765Z','2026-01-23T21:13:19.265Z',NULL,NULL,NULL,'https://upload.wikimedia.org/wikipedia/commons/e/e6/Waisenhaus_Zurich_Giacometti_Halle_%28Ank_Kumar%29_Infosys_Limited_11.jpg','Photo by Ank gsx, Wikimedia Commons','This is a photograph of the interior of Giacometti-Halle, featuring a painted ceiling and a mural on the back wall.','https://upload.wikimedia.org/wikipedia/commons/b/b9/Waisenhaus_Zurich_Giacometti_Halle_%28Ank_Kumar%29_Infosys_Limited_12.jpg','Photo by Ank gsx, Wikimedia Commons','The photo shows the interior of the Giacometti-Halle, featuring a beautifully decorated arched ceiling and stone pillars.','Die Giacometti-Halle oder Blüemlihalle ist die von dem Schweizer Maler Augusto Giacometti in den 1920er Jahren künstlerisch gestaltete Eingangshalle zum Amtsgebäude der Stadtpolizei Zürich. Das frühere Kellergewölbe eines Waisenhauses zählt heute zu den wichtigsten Sehenswürdigkeiten der Stadt Zürich und gilt als ein Kunstwerk nationaler Bedeutung.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (3,'Rudolf-Brun-Brücke',10913152,'Q27326206','de','47.3743800','8.5423100','Zürich','ZH','Bridge',100,'["Bauwerk aus Beton","Brücke in Europa","Brücke in Zürich","Erbaut in den 1910er Jahren","Erbaut in den 1980er Jahren","Limmatbrücke"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/2/27/7337_-_Z%C3%BCrich_-_Limmat_at_Rudolf-Brun-Br%C3%BCcke.JPG','Photo by Thisisbossi, Wikimedia Commons','wikipedia-de','This is a photo of the Rudolf-Brun-Brücke bridge in Zurich, Switzerland, with buildings and a church steeple in the background.',0,135,'2026-01-20T18:43:16.218Z','2026-01-23T21:14:11.173Z','https://upload.wikimedia.org/wikipedia/commons/f/f6/Amthaus_I_%28Waisenhaus-Stadtpolizei_Z%C3%BCrich%29_-_Limmatquai_2015-02-26_12-43-26.JPG','Photo by Roland zh, Wikimedia Commons','This is a photo of the Rudolf-Brun-Brücke bridge in Zurich, Switzerland, with buildings in the background.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Rudolf-Brun-Brücke führt in Zürich über die Limmat. Sie ist nach Rudolf Brun benannt, dem ersten Bürgermeister der Stadt. Bis 1951 wurde sie nach der Urania-Sternwarte als Uraniabrücke bezeichnet.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (4,'Urania-Sternwarte Zürich',4133188,'Q2500042','de','47.3743500','8.5394680','Zürich','ZH',NULL,0,'["Bauwerk aus Beton","Bauwerk des Historismus in Zürich","Bildungseinrichtung in Zürich","Erbaut 1907","Großteleskop (Optischer Bereich)","Kultur (Zürich)","Kulturgut von nationaler Bedeutung im Kanton Zürich","Volkssternwarte in der Schweiz","Wissenschaft in Zürich"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/a/a3/Amthaus_III_%26_Urania_Sternwarte_-_Lindenhofstrasse_2011-08-01_15-44-00_ShiftN.jpg','Photo by Roland zh, Wikimedia Commons','wikipedia-de','This is a photograph of the Urania-Sternwarte Zürich, showing its unique architecture with a dome and statues.',0,10,'2026-01-20T18:43:16.538Z','2026-01-23T21:15:16.281Z','https://upload.wikimedia.org/wikipedia/commons/5/5a/Amthaus_III_%26_Urania_Sternwarte_-_Lindenhofstrasse_2011-08-01_15-44-18_ShiftN2.jpg','Photo by Roland zh, Wikimedia Commons','This is a photograph of the Urania-Sternwarte Zürich, an observatory in Zurich, Switzerland, showing its distinctive dome and architectural details.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Urania-Sternwarte Zürich (offizielle Bezeichnung) ist eine Volkssternwarte im Quartier Lindenhof (Kreis 1) in Zürich. Sie ist die älteste Volkssternwarte der Schweiz. Ihren Namen Urania verdankt sie der Muse der Sternkunde aus der griechischen Mythologie – namentlich abgeleitet von Uranos, dem Himmel in Göttergestalt.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (5,'Lindenhof (Zürcher Hügelzug)',3759344,'Q39374','de','47.3730080','8.5407240','Zürich','ZH','Square',0,'["Geographie (Zürich)","Kulturgut von nationaler Bedeutung im Kanton Zürich","Platz in Europa","Platz in Zürich"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/8/81/2013-05-05_Zuriko_%28Foto_Dietrich_Michael_Weidmann%29_071.JPG','Photo by DidiWeidmann, Wikimedia Commons','wikipedia-de','This is a photograph of the Lindenhof area in Zurich, Switzerland, showing the cityscape, river, and surrounding hills.',0,84,'2026-01-20T18:43:17.128Z','2026-01-23T21:16:08.938Z','https://upload.wikimedia.org/wikipedia/commons/9/95/2013-05-05_Zuriko_%28Foto_Dietrich_Michael_Weidmann%29_072.JPG','Photo by DidiWeidmann, Wikimedia Commons','This is a photograph of the Lindenhof in Zurich, Switzerland, showing the city skyline and surrounding hills.','https://upload.wikimedia.org/wikipedia/commons/2/2c/2013_Sechsel%C3%A4uten_-_%27Willkomm%C3%A4_z%27St._Gall%C3%A4%27_-_%27Z%C3%BCri_iineh%21_d%27St._Galler_st%C3%B6nd_scho_z%27Rapperswil.%27_-_Lindenhof_2013-04-14_18-20-42_%28P7700%29.JPG','Photo by Roland zh, Wikimedia Commons','The photo shows the interior of a tent, decorated with green and white fabric, string lights, and potted plants, with people dining in the background.',NULL,NULL,NULL,'Der Lindenhof ist als Teil der eiszeitlichen Endmoräne und Hügelzug der historische Stadtkern und ein öffentlicher Platz der Schweizer Stadt Zürich.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (7,'Lindenhofbrunnen',13450324,'Q27229903','de','47.3729223','8.5412263','Zürich','ZH','Fountain',50,'["Brunnen in Zürich","Denkmal in Zürich","Erbaut im 17. Jahrhundert","Kulturgut von regionaler Bedeutung im Kanton Zürich"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/8/8b/Brunnen_Hedwig_ab_Burghalden.jpg','Photo by Jeannette Röthlisberger, Wikimedia Commons','wikipedia-de','This is a photograph of the Lindenhofbrunnen fountain in Zurich, Switzerland, with a statue on top, a small building next to it, and a cityscape in the background.',0,85,'2026-01-20T18:43:17.945Z','2026-01-23T21:16:53.228Z','https://upload.wikimedia.org/wikipedia/commons/a/ae/Brunnen_Lindenhof.jpg','Photo by Parpan05, Wikimedia Commons','This is a photo of the Lindenhofbrunnen fountain in Zurich, Switzerland, featuring a statue atop a column in a public square.',NULL,NULL,NULL,NULL,NULL,NULL,'Der Lindenhofbrunnen (im Volksmund auch Hedwigbrunnen) ist ein Figurenbrunnen auf dem Lindenhof in der Altstadt von Zürich. Der erste Vorgängerbau wurde zwischen 1666 und 1668 von Hans Georg Werdmüller errichtet. Die 1910 aufgestellte Bronzefigur zeigt die Sagenfigur Hedwig ab Burghalden und ist ein Werk von Gustav Siber.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (8,'Zürcher Spielzeugmuseum',3048335,'Q248517','de','47.3730980','8.5397820','Zürich','ZH','Museum',0,'["Museum in Zürich","Museumsgründung 1956","Spielzeugmuseum"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/1/13/Z%C3%BCricher_Spielzeugmuseum_1000687.jpg','Photo by Flominator, Wikimedia Commons','wikipedia-de','This is a photograph of the exterior entrance to the Zürcher Spielzeugmuseum (Toy Museum Zurich), featuring an arched doorway, steps, and signage.',0,84,'2026-01-20T18:43:18.486Z','2026-01-23T21:17:44.617Z','https://upload.wikimedia.org/wikipedia/commons/6/6d/Villa15_DSC5113_ShiftN_01.JPG','Photo by Ponte1112, Wikimedia Commons','This is a photograph of the Zürcher Spielzeugmuseum, a stately building surrounded by trees and a lawn.','https://upload.wikimedia.org/wikipedia/commons/5/5e/Z%C3%BCricher_Spielzeugmuseum_1000698.jpg','Photo by Cropbot, Wikimedia Commons','The photo shows a detailed miniature toy shop display, likely from the Zürcher Spielzeugmuseum, featuring cabinets, a scale, dolls, and various miniature goods.','https://upload.wikimedia.org/wikipedia/commons/2/2d/Z%C3%BCricher_Spielzeugmuseum_1000702.jpg','Photo by Flominator, Wikimedia Commons','The photo shows an antique toy store display case with various items on display, likely from the Zürcher Spielzeugmuseum.','Das Zürcher Spielzeugmuseum wurde im Jahre 1956 aus Anlass des 75-jährigen Bestehens des Unternehmens Franz Carl Weber von Margrit Weber-Beck gegründet. Im September 1981 zog es in das Haus Rennweg 26/Fortunagasse 15, einen der ältesten Winkel der Altstadt von Zürich unweit der Bahnhofstrasse. Im Herbst 2022 wurde das Museum an die Altstetterstrasse verlegt, wo auch die Verwaltung von Franz Carl Weber ihren Sitz hatte.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (9,'Mühlesteg',10930115,'Q27324054','de','47.3756000','8.5427300','Zürich','ZH','Bridge',100,'["Brücke in Europa","Brücke in Zürich","Erbaut in den 1980er Jahren","Fußgängerbrücke in der Schweiz","Limmatbrücke"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/b/b5/M%C3%BChlesteg_Z%C3%BCrich_2022-09-24_06.jpg','Photo by GPSLeo, Wikimedia Commons','wikipedia-de','This is a photograph of the Mühlesteg bridge in Zurich, Switzerland, with the city skyline in the background.',0,135,'2026-01-20T18:43:18.997Z','2026-01-23T21:19:16.531Z','https://upload.wikimedia.org/wikipedia/commons/7/7e/M%C3%BChlesteg_%C3%BCber_die_Limmat%2C_Stadt_Z%C3%BCrich-Altstadt_20180908-jag9889.jpg','Photo by Jag9889, Wikimedia Commons','This is a photograph of the Mühlesteg bridge in Zurich, Switzerland, with buildings and a swan in the water.',NULL,NULL,NULL,NULL,NULL,NULL,'Der Mühlesteg ist eine 1982 eröffnete Fussgängerbrücke über den Fluss Limmat in Zürich.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (10,'Mühlegasse 5',10671619,'Q61144757','de','47.3743900','8.5434900','Zürich','ZH','Building',0,'["Geschäftshaus","Wohngebäude in Zürich"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/5/57/7162_-_Z%C3%BCrich_-_View_from_Lindenhof.JPG','Photo by Thisisbossi, Wikimedia Commons','wikipedia-de','This is a photograph of a cityscape in Zurich, Switzerland, featuring a river, bridges, buildings, and a church steeple.',0,9,'2026-01-20T18:43:19.814Z','2026-01-23T21:19:24.397Z','https://upload.wikimedia.org/wikipedia/commons/4/45/Kino_Radium%2C_Z%C3%BCrich%2C_2014.jpg','Photo by Natalie Freyaldenhoven, Wikimedia Commons','This is a black and white photograph of the exterior of a building at Mühlegasse 5, featuring a painted facade with the words ''Kino Radium'' and various shops on the ground floor.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Mühlegasse 5 ist ein Wohn- und Geschäftshaus im Niederdorf der Zürcher Altstadt. Der östliche Teil des Gebäudes ist bereits in der Mitte des 14. Jahrhunderts entstanden.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (11,'Rennwegtor',7611434,'Q14544664','de','47.3739910','8.5385470','Zürich','ZH','Tower',100,'["Abgegangenes Bauwerk in Zürich","Befestigungsanlage in Zürich","Stadttor in der Schweiz","Turm in Europa","Wehrturm in der Schweiz","Zerstört in den 1860er Jahren"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/5/5e/Rennwegtor_1860.jpg','Photo by Parpan05, Wikimedia Commons','wikipedia-de','This is an illustration of the Rennwegtor, showing the gate and surrounding buildings with people and a horse.',0,135,'2026-01-20T18:43:20.259Z','2026-01-23T21:20:14.494Z','https://upload.wikimedia.org/wikipedia/commons/7/7d/Rennwegtor_Holzschnitt_1522.JPG','Photo by Parpan05, Wikimedia Commons','This is a black and white drawing of the Rennwegtor, a medieval gate and surrounding buildings.','https://upload.wikimedia.org/wikipedia/commons/0/0a/Rennwegtor_Glocke.JPG','Photo by Parpan05, Wikimedia Commons','The photo shows a large, old bell mounted on a wooden frame inside a building.',NULL,NULL,NULL,'Das Rennwegtor in Zürich war ein Teil der zweiten linksufrigen Stadtbefestigung. Es stand an der heutigen Ecke Rennweg-Bahnhofstrasse und sicherte den Zugang zur Stadt für den aus Westen und Süden kommenden Personen- und Fuhrwerkverkehr. Das Rennwegtor war der einzige befahrbare Zugang ins kleine oder mindere Zürich, den Stadtteil links der Limmat.');
