INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (390,'Gewerbemuseum Winterthur',6249048,'Q1520451','de','47.4992340','8.7294630','Winterthur','ZH','Museum',0,'["Kulturgut von regionaler Bedeutung im Kanton Zürich","Museum in Winterthur","Museumsgründung 1875"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/6/6d/Winterthur_Gewerbemuseum.jpg','Photo by Ikiwaner, Wikimedia Commons','wikipedia-de','This is a photograph of the Gewerbemuseum Winterthur, a white building with arched windows and the museum''s name displayed on the facade.',0,85,'2026-01-20T18:47:04.208Z','2026-01-23T21:57:17.615Z','https://upload.wikimedia.org/wikipedia/commons/1/1b/Uhrensammlung_Kellenberger_%28Gewerbemuseum%29%2C_Kirchplatz_14_in_Winterthur_2011-09-09_15-39-54_ShiftN.jpg','Photo by Roland zh, Wikimedia Commons','This is a photograph of the exterior of the Gewerbemuseum Winterthur, a building with a classical facade and arched entrances.','https://upload.wikimedia.org/wikipedia/commons/e/ee/Winterthur_Gewerbemuseum_Treppe.jpg','Photo by Ikiwaner, Wikimedia Commons','This is a photograph of a wooden staircase inside a building, possibly the Gewerbemuseum Winterthur, with a glass wall featuring colorful origami-like decorations.',NULL,NULL,NULL,'Das Gewerbemuseum Winterthur ist ein städtisches Museum in Winterthur, das bereits 1874 gegründet und 1875 eröffnet wurde. Es beschäftigt sich sowohl mit Gestaltung, Kunst und Gesellschaft, als auch etwa mit  Materialien, Produktion und Handwerk. Das Museum wird vom Bund im KGS-Inventar als B-Objekt gelistet und steht unter regionalem Denkmalschutz.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (391,'Stadtkirche Winterthur',7417901,'Q2327489','de','47.4989910','8.7286870','Winterthur','ZH','Square',100,'["Alban von England","Archäologischer Fundplatz in Winterthur","Disposition einer Orgel","Kirche in der Reformierten Kirche Kanton Zürich","Kirchengebäude in Winterthur","Kulturgut von nationaler Bedeutung im Kanton Zürich"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/8/8c/Church_Winterthur.jpg','Photo by Ssstini, Wikimedia Commons','wikipedia-de','The photo shows the exterior of the Stadtkirche Winterthur, featuring its two towers and clock.',0,85,'2026-01-20T18:47:04.738Z','2026-01-23T21:47:12.914Z','https://upload.wikimedia.org/wikipedia/commons/8/83/Kirchenplatz-winterthur.jpg','Photo by Raffaela Spataro, Wikimedia Commons','This is a photograph of the Stadtkirche Winterthur, featuring its distinctive towers and clock faces, taken from a street-level perspective.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Stadtkirche Winterthur ist die evangelisch-reformierte Stadtkirche von Winterthur und als solche eines der Wahrzeichen von Winterthur. Die Stadtkirche wird vom Bund in der Liste der Kulturgüter von nationaler Bedeutung im Kanton Zürich geführt. Sie erinnert an die drei Stadtheiligen St.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (392,'Kunsthalle Winterthur',6859895,'Q1792423','de','47.4996210','8.7290510','Winterthur','ZH','Museum',0,'["Kunstmuseum in Winterthur","Museumsgründung 1971"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/6/68/Ehemaliges_Waaghaus%2C_Marktgasse_25_in_Winterthur_2011-09-09_15-22-16_ShiftN.jpg','Photo by Roland zh, Wikimedia Commons','wikipedia-de','This is a photograph of the exterior of Kunsthalle Winterthur, a building with a distinctive red facade and arched entrances.',0,84,'2026-01-20T18:47:05.109Z','2026-01-23T21:47:16.315Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Die Kunsthalle Winterthur ist ein Kunstmuseum in Winterthur. Sie befindet sich im Obergeschoss des Ehemaligen Waaghauses in der Winterthurer Altstadt, das in der Liste der Kulturgüter von nationaler Bedeutung aufgeführt wird. Die Kunsthalle zeigt jährlich fünf bis sechs Wechselausstellungen zeitgenössischer Kunst, darunter internationale Positionen ebenso wie solche von Winterthurer Kunstschaffenden.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (393,'Marktgasse (Winterthur)',12732668,'Q117247784','de','47.4996610','8.7288690','Winterthur','ZH',NULL,0,'["Fußgängerzone in Winterthur","Innerortsstrasse in Winterthur"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/9/9e/Altstadt%2C_mittelalterliche-neuzeitliche_Stadt_Winterthur.jpg','Photo by Roland zh, Wikimedia Commons','wikipedia-de','This is a photograph of Marktgasse in Winterthur, Switzerland, showing colorful buildings, a statue on a column, and people walking along the street.',0,10,'2026-01-20T18:47:05.494Z','2026-01-23T20:57:38.367Z','https://upload.wikimedia.org/wikipedia/commons/2/21/Abnahme_der_Weihnachtsbeleuchtung_in_Winterthur_%282014%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','This is a photograph of Marktgasse in Winterthur, Switzerland, showing the street with buildings, people, and a truck with a lift installing Christmas decorations.',NULL,NULL,NULL,NULL,NULL,NULL,'Das Marktgasse ist eine etwa 335 m lange Strasse in Winterthur im Schweizer Kanton Zürich, die Teil der Winterthurer Altstadt und damit Teil der dortigen Fussgängerzone ist. Sie bildet zusammen mit dem Untertor und dem Obertor die Hauptachse durch die Winterthurer Altstadt.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (394,'Winterthurer Bibliotheken',5624460,'Q2585160','de','47.4986700','8.7294300','Winterthur','ZH','Library',0,'["Bibliothek in der Schweiz","Bildung in Winterthur","Bildungseinrichtungsgründung 1660","Kommunale Bibliothek","Kultur (Winterthur)","Kulturgut von nationaler Bedeutung im Kanton Zürich"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/e/e8/Bibliothek-Veltheim-Winterthur.jpg','Photo by Vatragora, Wikimedia Commons','wikipedia-de','The photo shows a traditional Swiss building with white walls, timber framing, and red shutters, located on a street corner.',0,84,'2026-01-20T18:47:05.858Z','2026-01-23T20:58:18.132Z','https://upload.wikimedia.org/wikipedia/commons/d/da/Stadtbibliothek_Winterthur_%282016%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','This is a photograph of the Winterthurer Bibliotheken, showing colorful buildings and a cobblestone street.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Winterthurer Bibliotheken sind das Bibliothekssystem der öffentlichen Bibliotheken der Stadt Winterthur. Hierzu gehören die Stadtbibliothek mit der Sammlung Winterthur (inklusive der ehemaligen Sondersammlungen) sowie sechs Quartierbibliotheken.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (395,'Haus zur Sonne (Winterthur)',9462449,'Q24206971','de','47.4996600','8.7298500','Winterthur','ZH',NULL,0,'["Bauwerk in Winterthur","Erbaut in den 1550er Jahren","Gasthaus in Europa","Gasthaus in der Schweiz","Gastronomiebetrieb (Schweiz)","Gotisches Bauwerk im Kanton Zürich","Kulturgut von regionaler Bedeutung im Kanton Zürich","Restaurant"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/e/ee/Haus_zur_Sonne%2C_Winterthur-IMG_2390.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','wikipedia-de','This is a photograph of the Haus zur Sonne in Winterthur, Switzerland, showing its distinctive architecture and surrounding buildings.',0,9,'2026-01-20T18:47:06.231Z','2026-01-23T20:58:33.563Z','https://upload.wikimedia.org/wikipedia/commons/3/38/Winterthur_Marktgasse_15.jpg','Photo by Wintiknipser, Wikimedia Commons','The photo shows the exterior of Haus zur Sonne in Winterthur, Switzerland, along with neighboring buildings, captured on a sunny day.',NULL,NULL,NULL,NULL,NULL,NULL,'Das Haus zur Sonne ist eine historische Gaststätte in Winterthur im Kanton Zürich in der Schweiz. Das im Jahr 1557 erbaute Gebäude gilt als eines der ältesten Gasthäuser der Stadt und ist als Kulturgut von regionaler Bedeutung eingestuft.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (396,'Haus zur Geduld',9522264,'Q26125083','de','47.4998800','8.7297700','Winterthur','ZH','Monument',50,'["Barockbauwerk im Kanton Zürich","Bauwerk in Winterthur","Denkmalschutzobjekt im Kanton Zürich","Erbaut 1690","Kulturgut von regionaler Bedeutung im Kanton Zürich"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/c/c8/Haus_zur_Geduld%2C_Marktgasse_22%2C_Winterthur%2C_Schweiz.jpg','Photo by NetHawk, Wikimedia Commons','wikipedia-de','This is a photograph of the facade of the Haus zur Geduld building, featuring its distinctive wooden door and oriel window.',0,85,'2026-01-20T18:47:06.707Z','2026-01-23T20:58:55.724Z','https://upload.wikimedia.org/wikipedia/commons/4/47/Winterthur_Marktgasse_22%2C_Haus_zur_Geduld.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','This is a photograph of the Haus zur Geduld building in Switzerland, featuring its distinctive bay window and stone facade.',NULL,NULL,NULL,NULL,NULL,NULL,'Das Haus zur Geduld ist ein barocker Profanbau in Winterthur im Kanton Zürich in der Schweiz. Es gilt als „bedeutendstes Werk des ausgehenden 17. Jahrhunderts in Winterthur“ und gehört zu den wenigen Altstadtgebäuden Winterthurs, die eine Natursteinfassade aufweisen.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (397,'Justitiabrunnen (Winterthur)',13212667,'Q29933296','de','47.4995500','8.7279800','Winterthur','ZH','Fountain',0,'["Bauwerk in Winterthur","Brunnen in der Schweiz","Erbaut im 18. Jahrhundert","Justitiabrunnen","Kulturgut von regionaler Bedeutung im Kanton Zürich","Rokokobauwerk in der Schweiz"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/9/95/Justitiabrunnen.jpg','Photo by Kulmalukko, Wikimedia Commons','wikipedia-de','This is a photograph of the Justitiabrunnen fountain in Winterthur, Switzerland, surrounded by buildings and people.',0,85,'2026-01-20T18:47:07.108Z','2026-01-23T20:59:34.142Z','https://upload.wikimedia.org/wikipedia/commons/b/b5/Winterthur_-_Altstadt%2C_mittelalterliche-neuzeitliche_Stadt_-_Marktgasse_2011-09-09_15-18-44.jpg','Photo by Roland zh, Wikimedia Commons','This is a photograph of the Justitiabrunnen (Justice Fountain) in Winterthur, Switzerland, situated in a pedestrian street lined with buildings.',NULL,NULL,NULL,NULL,NULL,NULL,'Der Justitiabrunnen (auch Gerechtigkeitsbrunnen, Themisbrunnen) ist ein frühneuzeitlicher Steinbrunnen in der historischen Altstadt von Winterthur in der Schweiz und wird im Schweizerischen Kulturgüterschutzinventar als Objekt von regionaler Bedeutung geführt. Er ist der älteste noch erhaltene Laufbrunnen und zusammen mit dem Fortunabrunnen am Obertor der einzige erhaltene vorindustrielle Figurenbrunnen der Stadt. In seiner heutigen Gestalt ist er 1748, zur Zeit des Rokoko, entstanden.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (398,'Judd-Brunnen',7511450,'Q15056904','de','47.4983000','8.7289860','Winterthur','ZH','Fountain',0,'["Bauensemble in der Schweiz","Bauwerk aus Beton","Bauwerk in Winterthur","Brunnen in der Schweiz","Erbaut 1997"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/8/87/Judd-Brunnen_mit_Spiegelung_in_Winterthur.jpg','Photo by File Upload Bot (Magnus Manske), Wikimedia Commons','wikipedia-de','This photo shows the Judd-Brunnen fountain in Zug, Switzerland, reflecting the surrounding buildings and sky.',0,84,'2026-01-20T18:47:07.353Z','2026-01-23T20:59:36.927Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Die Judd-Brunnen sind drei Brunnen in der Winterthurer Altstadt (Steinberggasse), die vom US-amerikanischen Minimalkünstler Donald Judd geschaffen wurden.
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (399,'Fischmädchenbrunnen',13219494,'Q113959627','de','47.4982735','8.7280739','Winterthur','ZH','Statue',0,'["Bauwerk aus Kalkstein","Bauwerk in Winterthur","Bronzeskulptur (Schweiz)","Brunnen in der Schweiz","Fischbrunnen","Frauenskulptur","Rekonstruiertes Bauwerk in der Schweiz","Skulptur (1938)","Versetztes Bauwerk in der Schweiz","Weiblicher Akt"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/f/fe/750_Jahre_Winterthur_-_Fischm%C3%A4dchenbrunnen_%26_Steinberggasse_%282014%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','wikipedia-de','This is a photograph of the Fischmädchenbrunnen (Fish Girl Fountain) in Schaffhausen, Switzerland, surrounded by buildings and people.',0,85,'2026-01-20T18:47:07.812Z','2026-01-23T21:00:07.941Z','https://upload.wikimedia.org/wikipedia/commons/d/d0/Fischm%C3%A4dchen-Brunnen_und_Metzggasse_in_Winterthur_%282014%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','The photo shows the Fischmädchenbrunnen (Fish Girl Fountain) in Stein am Rhein, Switzerland, with colorful buildings lining the street in the background.',NULL,NULL,NULL,NULL,NULL,NULL,'Der Fischmädchenbrunnen (auch Fischermädchenbrunnen, zürichdeutsch Fisch(er)meitlibrunne) ist ein Zierbrunnen auf der Steinberggasse in der Altstadt von Winterthur im Schweizer Kanton Zürich. Der Brunnentrog und der Brunnenstock stammen aus dem Jahr 1861, die Bronzeplastik von Max Reinhold Weber wurde 1938 hinzugefügt.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (400,'Kunst Museum Winterthur – Reinhart am Stadtgarten',1334174,'Q689829','de','47.5004000','8.7290000','Winterthur','ZH','Museum',0,'["Kulturgut von nationaler Bedeutung im Kanton Zürich","Kunst Museum Winterthur – Reinhart am Stadtgarten","Kunstmuseum in Winterthur","Museumsgründung 1951"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/f/fb/Kunst_Museum_Winterthur_Reinhart_am_Stadtgarten_%282019%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','wikipedia-de','This is a photograph of the Kunst Museum Winterthur – Reinhart am Stadtgarten, showing the building''s facade, a banner, a lamppost, and a fountain.',0,85,'2026-01-20T18:47:08.625Z','2026-01-23T21:01:56.018Z','https://upload.wikimedia.org/wikipedia/commons/a/a7/Caspar_David_Friedrich%27s_Chalk_Cliffs_on_R%C3%BCgen.jpg','Photo by Benison, Wikimedia Commons','A painting depicts a coastal scene with white cliffs, trees framing the view, and three figures in the foreground.','https://upload.wikimedia.org/wikipedia/commons/f/f2/Kunst_Museum_Winterthur_Reinhart_am_Stadtgarten_2023_09.jpg','Photo by Iopensa, Wikimedia Commons','The photo shows a painting of five women in blue dresses holding hands, hanging on a wall in a museum.','https://upload.wikimedia.org/wikipedia/commons/c/c7/Kunst_Museum_Winterthur_Reinhart_am_Stadtgarten_2023_12.jpg','Photo by Iopensa, Wikimedia Commons','The photo shows an interior view of the Kunst Museum Winterthur, featuring paintings on the wall and a doorway leading to another gallery.','Das Kunst Museum Winterthur | Reinhart am Stadtgarten, vormals Museum Oskar Reinhart, ist ein Kunstmuseum in Winterthur im Schweizer Kanton Zürich. Es befindet sich angrenzend zur Altstadt an der Stadthausstrasse, umgeben vom Stadtgarten. Seit 2018 wird es vom Kunstverein Winterthur unter dem Dach des Kunst Museum Winterthur geführt zusammen mit dem ehemaligen Kunstmuseum Winterthur und der Villa Flora.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (401,'Sammlung Briner und Kern',6732189,'Q1670093','de','47.5004000','8.7290000','Winterthur','ZH','Museum',0,'["Ehemaliges Museum in der Schweiz","Kunstmuseum in Winterthur"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/5/5c/Egbert_van_der_Poel_-_Seashore_by_Moonlight_-_WGA17993.jpg','Photo by JarektUploadBot, Wikimedia Commons','wikipedia-de','This painting depicts a nighttime scene with boats and figures on a beach under a full moon.',0,83,'2026-01-20T18:47:09.372Z','2026-01-23T21:02:19.758Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Die Sammlung Briner und Kern war von 1970 bis zum 31. Oktober 2014 im Museum Briner und Kern im Rathaus von Winterthur untergebracht. Die Gemälde der Stiftung Jakob Briner sind seit Oktober 2016 in einem eigenen Flügel des Museums Oskar Reinhart ausgestellt.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (402,'Altes Stadthaus (Winterthur)',10930382,'Q29933273','de','47.4993400','8.7271100','Winterthur','ZH',NULL,0,'["Bauwerk in Winterthur","Erbaut in den 1790er Jahren","Klassizistisches Bauwerk in der Schweiz","Kultur (Winterthur)","Kulturgut von regionaler Bedeutung im Kanton Zürich","Spielstätte für Musik in der Schweiz","Veranstaltungsstätte in Winterthur","Verwaltungsbau"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/5/5d/Altes_Stadthaus%2C_Marktgasse_53%2C_Winterthur_IMG_2479.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','wikipedia-de','The photo shows the Altes Stadthaus in Winterthur, Switzerland, along with adjacent buildings, from a street-level perspective.',0,9,'2026-01-20T18:47:09.807Z','2026-01-23T21:02:26.565Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Das Alte Stadthaus ist ein frühklassizistisches Gebäude in der Marktgasse 53 in der Altstadt von Winterthur. Es steht unter Kulturgüterschutz (Kategorie B) steht und wurde 1790 durch den Architekten Diethelm Schneider erbaut. Ursprünglich waren hier die Spitalverwaltung und im Hinterhaus das Obere Spital ansässig.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (403,'Sommertheater Winterthur',6860471,'Q2300623','de','47.5003950','8.7275510','Winterthur','ZH','Theatre',0,'["Aufgelöst 2022","Ehemaliges Theater","Freilichtbühne in der Schweiz","Gegründet 1881","Theater (Winterthur)"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/8/8f/Eingangsgeb%C3%A4ude_Sommertheater_Winterthur.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','wikipedia-de','This is a photo of the exterior of the Sommertheater Winterthur, a summer theater in Winterthur, Switzerland.',0,84,'2026-01-20T18:47:10.452Z','2026-01-23T21:02:30.869Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Das Sommertheater Winterthur war ein Freilichttheater in Winterthur. Es bestand von 1865 bis 2022 und war damit bis zu seiner Schliessung das älteste Theater der Stadt. Spielzeit war jeweils von Juni bis September.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (404,'Casinotheater Winterthur',6072216,'Q116060080','de','47.4997510','8.7266020','Winterthur','ZH','Monument',50,'["Bauwerk in Winterthur","Denkmalschutzobjekt im Kanton Zürich","Kleinbühne","Kulturgut von regionaler Bedeutung im Kanton Zürich","Theater (Winterthur)"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/e/e6/Casinotheater_Winterthur_%282014%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','wikipedia-de','This is a photograph of the exterior of the Casinotheater Winterthur in Winterthur, Switzerland, showing the building''s facade, street, and some surrounding buildings.',0,85,'2026-01-20T18:47:10.886Z','2026-01-23T21:02:37.962Z','https://upload.wikimedia.org/wikipedia/commons/2/22/CasinoTheater_Winterthur.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','This is a photograph of the Casinotheater Winterthur building in Switzerland.',NULL,NULL,NULL,NULL,NULL,NULL,'Das Casinotheater Winterthur ist ein Theater in Winterthur im Kanton Zürich in der Schweiz. Es liegt in der Altstadt an der Stadthausstrasse. Es wurde 2002 gegründet und wird von Künstlern getragen.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (405,'Stadtgarten (Winterthur)',9064901,'Q24037826','de','47.5009060','8.7282390','Winterthur','ZH','Park',0,'["Parkanlage in Winterthur"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/3/37/Bunter_Stadtgarten_Winterthur.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','wikipedia-de','This photo shows a colorful fence in Stadtgarten (Winterthur), with trees and a building in the background.',0,84,'2026-01-20T18:47:11.240Z','2026-01-23T21:03:27.388Z','https://upload.wikimedia.org/wikipedia/commons/7/7f/Stadtgarten_28_Winterthur.jpg','Photo by Jnmths, Wikimedia Commons','This is a photograph of Stadtgarten in Winterthur, showing trees, benches, and a lamp post in a park setting.',NULL,NULL,NULL,NULL,NULL,NULL,'Der Stadtgarten ist ein Stadtpark im Zentrum Winterthurs. Er erstreckt sich über eine Fläche von 22''743 m² ist mit seiner Lage direkt neben der Altstadt der am zentralsten gelegene Park der Stadt.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (406,'Alte Kaserne (Winterthur)',2982277,'Q435662','de','47.4979800','8.7312400','Winterthur','ZH','Monument',50,'["Barockbauwerk im Kanton Zürich","Bauwerk in Winterthur","Denkmalschutzobjekt im Kanton Zürich","Ehemalige Kaserne","Erbaut in den 1760er Jahren","Fachwerkgebäude in der Schweiz","Kaserne in der Schweiz","Kavalleriekaserne","Kultur (Winterthur)","Kulturgut von regionaler Bedeutung im Kanton Zürich","Kulturzentrum (Schweiz)","Militärgeschichte (Kanton Zürich)","Veranstaltungsstätte in Winterthur"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/0/03/Picswiss_ZH-13-10.jpg','Photo by Dake~commonswiki, Wikimedia Commons','wikipedia-de','The photo shows the exterior of the Alte Kaserne, a half-timbered building in Winterthur, Switzerland.',0,85,'2026-01-20T18:47:11.407Z','2026-01-23T21:03:43.516Z','https://upload.wikimedia.org/wikipedia/commons/9/91/Alt_Winterthur_Zeughaus.jpg','Photo by Spartanbu, Wikimedia Commons','This is a black and white photograph of the Alte Kaserne in Winterthur, featuring its distinctive timber-framed architecture and a vintage tram in front.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Alte Kaserne ist ein Kulturzentrum in der Stadt Winterthur. Der Fachwerkbau diente einst als Unterkunft für Rekruten. Das Gebäude ist im KGS-Inventar als B-Objekt geführt und steht unter regionalem Denkmalschutz.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (407,'Haus zum Warteck',7539938,'Q8988762','de','47.5003500','8.7313500','Winterthur','ZH',NULL,0,'["Bauwerk in Winterthur","Erbaut 1861","Kulturgut von nationaler Bedeutung im Kanton Zürich","Neorenaissancebauwerk in der Schweiz","Wohn- und Geschäftshaus in Europa","Wohn- und Geschäftshaus in der Schweiz"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/9/9b/Stadthausstrasse_39_in_Winterthur_%282014%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','wikipedia-de','The photo shows the facade of the Haus zum Warteck building, featuring a large wooden door, windows, and flags.',0,10,'2026-01-20T18:47:11.794Z','2026-01-23T21:04:06.764Z','https://upload.wikimedia.org/wikipedia/commons/9/91/Winterthur_Stadthausstrasse_39.jpg','Photo by AndreasPraefcke, Wikimedia Commons','This is a photograph of the Haus zum Warteck, a large, symmetrical building with a prominent entrance and flowerbeds in front.',NULL,NULL,NULL,NULL,NULL,NULL,'Das Haus zum Warteck ist ein Wohn- und Geschäftshaus in der Winterthurer Altstadt an Ecke Graben/Stadthausstrasse. Der im Stil der Neorenaissance erbaute Stadtpalast wird vom Bund in der Liste der Kulturgüter von nationaler Bedeutung geführt.');
