INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (561,'Stadtturm (Baden)',4375653,'Q1495183','de','47.4731600','8.3079100','Baden','AG','Monument',100,'["Bauwerk in Baden AG","Befestigungsanlage im Kanton Aargau","Denkmalschutzobjekt im Kanton Aargau","Erbaut in den 1440er Jahren","Kulturgut von regionaler Bedeutung im Kanton Aargau","Stadttor in der Schweiz","Torturm in der Schweiz","Turm in Europa"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/2/2a/Altstadt-Turm_in_Baden_-_panoramio.jpg','Photo by Panoramio upload bot, Wikimedia Commons','wikipedia-de','This is a photograph of the Stadtturm (Baden) clock tower, viewed through an archway, with surrounding buildings and a fountain.',0,80,'2026-01-20T21:37:32.740Z','2026-01-21T20:19:41.727Z','https://upload.wikimedia.org/wikipedia/commons/5/56/Aussenseite_des_Stadtturms_Baden%2C_Aargau_%282021%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','This is a photograph of the Stadtturm (Baden) in Switzerland, a tall clock tower surrounded by buildings and a public square.',NULL,NULL,NULL,NULL,NULL,NULL,'Der Stadtturm (ursprünglich Bruggerturm oder Baderturm genannt) ist ein Torturm in der Altstadt von Baden in der Schweiz. Er entstand in der Mitte des 15. Jahrhunderts und diente als nördliches Stadttor.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (562,'Stadtpfarrkirche Maria Himmelfahrt (Baden)',4155354,'Q2327817','de','47.4725800','8.3087900','Baden','AG','Church',100,'["Bauwerk in Baden AG","Erbaut in den 1460er Jahren","Gotisches Bauwerk im Kanton Aargau","Kirche in der Römisch-Katholischen Kirche im Aargau","Kirchengebäude im Kanton Aargau","Kulturgut von nationaler Bedeutung im Kanton Aargau","Mariä-Himmelfahrt-Kirche","Museum im Kanton Aargau","Pfarrkirche in der Schweiz"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/0/00/Baden_Stadtkirche.jpg','Photo by Badener, Wikimedia Commons','wikipedia-de','This is a photograph of the Stadtpfarrkirche Maria Himmelfahrt (Baden), showing its exterior architecture including the tower and roof.',0,130,'2026-01-20T21:37:46.629Z','2026-01-21T20:20:22.132Z','https://upload.wikimedia.org/wikipedia/commons/e/e2/Baden_-_Stadtkirche_-_Schartenfels_20100524_14-53-50.JPG','Photo by Roland zh, Wikimedia Commons','This is a photograph of the Stadtpfarrkirche Maria Himmelfahrt (Baden) church, surrounded by buildings and trees.','https://upload.wikimedia.org/wikipedia/commons/9/9a/Baden_Stadtkirche_Innenraum.jpg','Photo by Badener, Wikimedia Commons','The photo shows the interior of the Stadtpfarrkirche Maria Himmelfahrt (Baden), focusing on the altar and surrounding decorations.',NULL,NULL,NULL,'Die Stadtpfarrkirche Maria Himmelfahrt ist die römisch-katholische Pfarrkirche in Baden in der Schweiz. Sie gehört zur Katholischen Kirchgemeinde Baden-Ennetbaden (Pastoralraum Aargauer Limmattal) im Bistum Basel. 
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (563,'Hotel zum wilden Mann',11681492,'Q19362290','de','47.4727900','8.3074500','Baden','AG','Monument',50,'["Bauwerk in Baden AG","Denkmalschutzobjekt im Kanton Aargau","Ehemaliges Hotel in der Schweiz","Erbaut im 16. Jahrhundert","Gotisches Bauwerk im Kanton Aargau","Hotelbau in Europa","Hotelbau in der Schweiz","Kultur (Baden AG)","Kulturgut von nationaler Bedeutung im Kanton Aargau","Unternehmen (Baden AG)"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/5/56/20120921_Zum_wilden_Mann_02.jpg','Photo by Harubaba, Wikimedia Commons','wikipedia-de','This is a photograph of the Hotel zum wilden Mann, showing the exterior of the building and the narrow street it''s located on.',0,80,'2026-01-20T21:38:00.006Z','2026-01-21T20:20:53.681Z','https://upload.wikimedia.org/wikipedia/commons/2/23/20120921_Zum_wilden_Mann_01.jpg','Photo by Harubaba, Wikimedia Commons','The photo shows a narrow alleyway with buildings on either side, including the "Hotel zum wilden Mann" with a banner for "Bar Nouba-Lounge-Restaurant".',NULL,NULL,NULL,NULL,NULL,NULL,'Das Hotel zum Wilden Mann ist ein ehemaliges Hotel in Baden im Kanton Aargau. Es steht an der Oberen Gasse in der Altstadt und ist als eines der bedeutendsten Bürgerhäuser Badens ein Kulturgut von nationaler Bedeutung.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (564,'Historisches Museum Baden',8485605,'Q18625677','de','47.4733000','8.3108480','Baden','AG','Museum',50,'["Archäologische Sammlung in der Schweiz","Historisches Museum in der Schweiz","Kultur (Baden AG)","Kulturgut von regionaler Bedeutung im Kanton Aargau","Museum im Kanton Aargau","Museumsgründung 1875","Organisation (Baden AG)","Regionalmuseum"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/9/9f/Historisches_museum_landvogteischloss.jpg','Photo by Lukatbaden, Wikimedia Commons','wikipedia-de','This is a photograph of the Historisches Museum Baden, featuring a tower and a covered bridge over a river, with surrounding buildings and greenery.',0,80,'2026-01-20T21:38:14.568Z','2026-01-21T20:21:32.025Z','https://upload.wikimedia.org/wikipedia/commons/7/79/Holzbr%C3%BCcke_und_Landvogteischloss.jpg','Photo by Cnatercartier, Wikimedia Commons','The photo shows the Historisches Museum Baden, a tall building next to a covered bridge over a river.',NULL,NULL,NULL,NULL,NULL,NULL,'Das Historische Museum Baden ist ein Geschichtsmuseum in der Schweizer Stadt Baden im Kanton Aargau. Es beherbergt Relikte aus der über 2000-jährigen Geschichte von Stadt und Region und ist im Landvogteischloss und dessen Erweiterungsbau untergebracht. Der Erweiterungsbau entstand 1992/1993 nach Plänen von Wilfrid und Katharina Steib und wird im Volksmund aufgrund seiner geschwungenen Form als «Melonenschnitz» bezeichnet.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (565,'Landvogteischloss Baden',774150,'Q1480000','de','47.4730389','8.3109194','Baden','AG','Monument',100,'["Bauwerk in Baden AG","Denkmalschutzobjekt im Kanton Aargau","Erbaut in den 1490er Jahren","Kulturgut von regionaler Bedeutung im Kanton Aargau","Schloss im Kanton Aargau","Schloss in Europa"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/b/ba/Baden_-_Landvogteischloss_20100524_14-38-58_ShiftN.jpg','Photo by Roland zh, Wikimedia Commons','wikipedia-de','This is a photograph of the Landvogteischloss Baden connected to a covered bridge over a river.',0,80,'2026-01-20T21:38:28.873Z','2026-01-21T20:22:26.065Z','https://upload.wikimedia.org/wikipedia/commons/3/31/Baden_AG_-_gedeckte_Holzbr%C3%BCcke%2C_Limmat_%26_Landvogteischloss_%282021%29.jpg','Photo by JoachimKohler-HB, Wikimedia Commons','This is a photograph of the Landvogteischloss Baden and the covered wooden bridge over the Limmat river in Baden, Switzerland.',NULL,NULL,NULL,NULL,NULL,NULL,'Das Landvogteischloss ist ein kleines Schloss in der Stadt Baden im Schweizer Kanton Aargau. Es befindet sich am rechten Ufer der Limmat gegenüber der Altstadt und bewachte einst die Engstelle zwischen dem Schlossberg im Westen (mit der Burg Stein) und der Lägern im Osten. Bis 1798 war es die Residenz des Landvogts der Grafschaft Baden, heute beherbergt es das Historische Museum Baden und das Archiv der Stadt Baden.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (566,'Holzbrücke (Baden)',4308836,'Q1625435','de','47.4726400','8.3106100','Baden','AG','Bridge',100,'["Bauwerk in Baden AG","Brücke im Kanton Aargau","Brücke in Europa","Denkmalschutzobjekt im Kanton Aargau","Erbaut in den 1810er Jahren","Gedeckte Brücke","Holzbrücke in der Schweiz","Industriekulturpfad Limmat–Wasserschloss","Kulturgut von nationaler Bedeutung im Kanton Aargau","Strassenbrücke in der Schweiz"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/b/ba/Baden_-_Landvogteischloss_20100524_14-38-58_ShiftN.jpg','Photo by Roland zh, Wikimedia Commons','wikipedia-de','This is a photograph of the Holzbrücke (Baden), a covered wooden bridge connecting a building over a river.',0,130,'2026-01-20T21:38:41.391Z','2026-01-21T20:23:29.288Z','https://upload.wikimedia.org/wikipedia/commons/9/97/Baden_AG_-_Blick_auf_die_Altstadt_von_Baden.jpg','Photo by PantaRhei, Wikimedia Commons','This is a photograph of the Holzbrücke (wooden bridge) in Baden, Switzerland, with the town''s buildings and river visible.','https://upload.wikimedia.org/wikipedia/commons/9/90/Baden_AG_-_Gedeckte_Holzbr%C3%BCcke_-_Bild_5.jpg','Photo by PantaRhei, Wikimedia Commons','This is a photograph of the interior of the Holzbrücke (Baden), a covered wooden bridge.','https://upload.wikimedia.org/wikipedia/commons/4/4d/Baden_AG_-_Gedeckte_Holzbr%C3%BCcke_-_Bild_6.jpg','Photo by PantaRhei, Wikimedia Commons','The photo shows the interior of the Holzbrücke (Baden), a covered wooden bridge with intricate timber framing.','Die Holzbrücke ist eine Brücke in Baden in der Schweiz und überquert die Limmat an der engsten Stelle der Klus zwischen Schlossberg und Lägern. Sie ist 39 Meter lang und führt von der linksufrigen Altstadt zum Landvogteischloss am rechten Ufer. Die heute bestehende, gedeckte Holzbrücke hatte seit dem Mittelalter mindestens fünf Vorgängerbauten an derselben Stelle.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (567,'Sankt-Nikolaus-Kapelle (Baden)',3756945,'Q2222046','de','47.4731800','8.3063100','Baden','AG','Church',100,'["Bauwerk in Baden AG","Kirche in der Römisch-Katholischen Kirche im Aargau","Kirchengebäude im Kanton Aargau","Kulturgut von regionaler Bedeutung im Kanton Aargau","Nikolaikirche"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/1/11/Stein_2954.JPG','Photo by Badener, Wikimedia Commons','wikipedia-de','The Sankt-Nikolaus-Kapelle in Baden, Switzerland, sits atop a rocky hill with a Swiss flag waving from a tower.',0,130,'2026-01-20T21:38:53.245Z','2026-01-21T20:23:45.003Z','https://upload.wikimedia.org/wikipedia/commons/7/7a/Baden_-_Schlossruine_Stein_3.jpg','Photo by RicciSpeziari~commonswiki, Wikimedia Commons','The photo shows the Sankt-Nikolaus-Kapelle (Baden), a small chapel with a bell tower, partially obscured by tree branches.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Sankt-Nikolaus-Kapelle ist eine Kapelle in Baden in der Schweiz. Sie steht auf dem Grat des Schlossbergs und war im Mittelalter die Hofkapelle von Burg Stein.
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (568,'Schlossberg (Baden)',9846899,'Q31842285','de','47.4731500','8.3062000','Baden','AG','Mountain',0,'["Berg im Kanton Aargau","Berg in Europa","Berg unter 1000 Meter","Geographie (Baden AG)"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/5/53/Baden_Switzerland_Cityview.JPG','Photo by Dominique.bugmann, Wikimedia Commons','wikipedia-de','This is a photograph of Schlossberg in Baden, Switzerland, featuring the castle ruins, the old town, a bridge, and a church.',0,30,'2026-01-20T21:39:05.800Z','2026-01-21T20:23:50.704Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Der Schlossberg ist ein markanter Hügel in Baden im Kanton Aargau. Er ist 457 m hoch und erhebt sich rund 80 Höhenmeter über der Badener Altstadt. Der Schlossberg bildet das östliche Ende eines Höhenzugs zwischen Limmattal und Reusstal, der seine Fortsetzung im 539 m hohen Hundsbuck und der Müseren-Hochebene findet.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (569,'Ruine Stein',774778,'Q687130','de','47.4731611','8.3054500','Baden','AG','Castle',100,'["Bauwerk in Baden AG","Burg in Europa","Burgruine im Kanton Aargau","Denkmalschutzobjekt im Kanton Aargau","Festung in Europa","Festung in der Schweiz","Kulturgut von nationaler Bedeutung im Kanton Aargau"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/1/15/2012-11-02_15.29.59_Schloss_Stein.jpg','Photo by LuFiLa, Wikimedia Commons','wikipedia-de','The photo shows the Ruine Stein, a castle ruin with a flag on top, situated on a hill with trees and a small building.',0,130,'2026-01-20T21:39:18.528Z','2026-01-21T20:24:43.741Z','https://upload.wikimedia.org/wikipedia/commons/3/3d/Baden_AG_-_Ruine_Stein_Bild_1_2018.jpg','Photo by PantaRhei, Wikimedia Commons','The photo shows the exterior of the Ruine Stein, a stone castle ruin, with a cloudy sky in the background.','https://upload.wikimedia.org/wikipedia/commons/8/80/Baden_AG_-_Ruine_Stein_Bild_3_2018.jpg','Photo by PantaRhei, Wikimedia Commons','The photo shows a sign with information and drawings about Ruine Stein.',NULL,NULL,NULL,'Die Ruine Stein ist die Ruine einer Höhenburg auf 445 m ü. M. in Baden im Schweizer Kanton Aargau. Sie überragt die  Altstadt und sicherte einst zusammen mit dem Landvogteischloss am Ufer der Limmat die enge Klus zwischen Schlossberg und Lägern.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (570,'Hochbrücke (Baden)',4308925,'Q1621701','de','47.4716800','8.3108700','Baden','AG','Bridge',100,'["Bauwerk in Baden AG","Bogenbrücke","Brücke im Kanton Aargau","Brücke in Europa","Erbaut in den 1920er Jahren","Limmatbrücke","Stahlbetonbrücke","Strassenbrücke in der Schweiz"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/3/39/Baden_2012-08-17_17.04.50.jpg','Photo by Badener, Wikimedia Commons','wikipedia-de','The photo shows the Hochbrücke bridge in Baden, Switzerland, with the old town and Stein Castle in the background.',0,130,'2026-01-20T21:39:33.990Z','2026-01-21T20:25:33.800Z','https://upload.wikimedia.org/wikipedia/commons/6/6c/Baden_AG_-_Limmat_Hochbr%C3%BCcke.jpg','Photo by PantaRhei, Wikimedia Commons','This is a photograph of the Hochbrücke bridge in Baden, Switzerland, spanning a river with trees and buildings in the background.','https://upload.wikimedia.org/wikipedia/commons/5/55/Baden_Hochbruecke_Innen.jpg','Photo by Karzer, Wikimedia Commons','The photo shows the interior of a concrete structure with columns and stairs, possibly the support structure of a bridge.',NULL,NULL,NULL,'Die Hochbrücke ist eine Bogenbrücke in Baden in der Schweiz. Sie wurde 1926 eröffnet, ist 275 Meter lang und besitzt eine Hauptspannweite von 72 Metern. In einer Höhe von 24 Metern überspannt sie den Fluss Limmat.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (571,'Schulhausplatz (Baden)',9846369,'Q29057461','de','47.4716200','8.3063800','Baden','AG','Square',0,'["Bauwerk in Baden AG","Platz in Europa","Platz in der Schweiz"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/1/1e/Baden_AG_Schulhausplatz_4115563.jpg','Photo by Bobo11, Wikimedia Commons','wikipedia-de','This is a high-angle photograph of a street in Baden, Switzerland, lined with buildings and trees, with cars driving along the road.',0,80,'2026-01-20T21:39:50.520Z','2026-01-21T20:26:38.290Z','https://upload.wikimedia.org/wikipedia/commons/3/3b/Baden_AG_Schulhausplatz_4115564.jpg','Photo by Bobo11, Wikimedia Commons','This is an aerial view of Schulhausplatz in Baden, Switzerland, showing buildings, a road with cars, and surrounding greenery.',NULL,NULL,NULL,NULL,NULL,NULL,'Der Schulhausplatz ist ein wichtiger Verkehrsknotenpunkt in Baden im Kanton Aargau. Er ist Kreuzungspunkt von vier bedeutenden Hauptstrassen und gehört zu den verkehrsreichsten Plätzen der Schweiz. Benannt ist er nach dem 1856/57 erbauten Bezirksgebäude an seiner Südseite, das ursprünglich als Schulhaus genutzt wurde.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (572,'Kapuzinerkloster Baden',8375357,'Q18021669','de','47.4711800','8.3068600','Baden','AG','Monastery',0,'["Abgegangenes Bauwerk in der Schweiz","Ehemaliges Kapuzinerkloster in der Schweiz","Ehemaliges Kloster im Kanton Aargau","Klostergründung 1591","Organisation (Baden AG)","Zerstört in den 1850er Jahren"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/e/e5/Baden%2C_Aargau%2C_Bezirksgeb%C3%A4ude%2C_Luftbild.jpg','Photo by Voyager, Wikimedia Commons','wikipedia-de','This is a photograph of the Kapuzinerkloster Baden, a large building with a distinctive roof, taken from a high angle.',0,130,'2026-01-20T21:40:08.706Z','2026-01-21T20:26:49.135Z','https://upload.wikimedia.org/wikipedia/commons/7/73/Kloster_muri.jpg','Photo by Voyager, Wikimedia Commons','The photo shows the Kapuzinerkloster Baden, a monastery complex with a church featuring red spires, viewed from a distance with trees in the foreground.','https://upload.wikimedia.org/wikipedia/commons/5/51/Rudolf_Schellenberg_Kapuziner.jpg','Photo by Docteur Ralph, Wikimedia Commons','A painting depicts a monk kneeling in prayer before a crucifix.',NULL,NULL,NULL,'Das Kapuzinerkloster Baden ist ein ehemaliges Kloster des Kapuzinerordens in der Stadt Baden, Kanton Aargau in der Schweiz. Die Grundsteinlegung für den ersten Klosterbau ausserhalb des Stadtbachgrabens erfolgte 1591. Das Kloster wurde 1841 aufgehoben.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (573,'Reformierte Kirche Baden',2614857,'Q2136827','de','47.4765480','8.3091480','Baden','AG','Church',100,'["Barockbauwerk im Kanton Aargau","Barocke Kirche","Bauwerk in Baden AG","Denkmalschutzobjekt im Kanton Aargau","Erbaut in den 1710er Jahren","Kirche in der Reformierten Kirche Aargau","Kirchengebäude im Kanton Aargau","Kulturgut von nationaler Bedeutung im Kanton Aargau","Saalkirche in der Schweiz"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/f/f7/Baden_reformierte_Kirche_9379.jpg','Photo by Badener, Wikimedia Commons','wikipedia-de','This is a photograph of the Reformierte Kirche Baden, a white church with a black roof and a tall tower, taken from a low angle.',0,130,'2026-01-20T21:40:21.819Z','2026-01-21T20:27:29.508Z','https://upload.wikimedia.org/wikipedia/commons/d/d5/Baden-Pfarrkirche-2.jpg','Photo by Roland Zumbuehl, Wikimedia Commons','This is a photograph of the Reformierte Kirche Baden, a white church with a dark roof and spire, set against a blue sky.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Reformierte Kirche Baden ist heute die zentrale Kirche der reformierten Kirchgemeinde Baden in der Schweiz, die mit ihren Teilkirchgemeinden Baden-Ennetbaden, Ehrendingen-Freienwil, Obersiggenthal und Untersiggenthal die grösste Gemeinde der Reformierten Landeskirche Aargau bildet. Als die barocke Kirche zu Beginn des 18. Jahrhunderts erbaut wurde, gab es jedoch in der Stadt Baden keine reformierte Gemeinde.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (574,'Bahnhof Baden',4031641,'Q800441','de','47.4764580','8.3075140','Baden','AG','Station',50,'["Bahnhof im Kanton Aargau","Bahnhof in Europa","Bahnstrecke Zürich–Baden","Bauwerk in Baden AG","Bözbergstrecke","Denkmalschutzobjekt im Kanton Aargau","Erbaut 1847","Industriekulturpfad Limmat–Wasserschloss","Kulturgut von nationaler Bedeutung im Kanton Aargau"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/1/19/20120921_-_Bahnhof_Baden_%28Schweiz%29_vom_Bahnhofplatz_aus_gesehen.jpg','Photo by Harubaba, Wikimedia Commons','wikipedia-de','This is a photograph of the Baden train station, a yellow and white building with green shutters and a blue and red sign.',0,5,'2026-01-20T21:40:47.982Z','2026-01-21T20:17:28.391Z','https://upload.wikimedia.org/wikipedia/commons/9/9f/Baden_-_Bahnhof_20100524_14-16-50_ShiftN.jpg','Photo by Roland zh, Wikimedia Commons','This is a photograph of the Baden train station in Switzerland, featuring its classic architecture and a modern glass addition.',NULL,NULL,NULL,NULL,NULL,NULL,'Der Bahnhof Baden (CH) der Schweizerischen Bundesbahnen (SBB) ist der Bahnhof der Stadt Baden im Kanton Aargau. Er wurde 1847 als Endstation der Schweizerischen Nordbahn («Spanisch-Brötli-Bahn»), der zweiten Eisenbahnlinie der Schweiz, eröffnet und ist somit einer der ältesten Bahnhöfe des Landes. Das von Ferdinand Stadler entworfene Stationsgebäude ist das älteste der Schweiz, welches im Originalzustand erhalten geblieben ist und heute noch für den Bahnbetrieb genutzt wird.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (575,'St.-Anna-Kapelle (Baden)',4391986,'Q2315891','de','47.4721200','8.3127500','Baden','AG','Church',50,'["Annakirche","Bauwerk in Baden AG","Denkmalschutzobjekt im Kanton Aargau","Erbaut in den 1480er Jahren","Gotisches Bauwerk im Kanton Aargau","Kirchengebäude im Bistum Basel","Kirchengebäude im Kanton Aargau","Kulturgut von regionaler Bedeutung im Kanton Aargau"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/8/81/Baden_Annakapelle.jpg','Photo by Voyager, Wikimedia Commons','wikipedia-de','The photo shows the exterior of the St.-Anna-Kapelle in Baden, Switzerland, a simple building with a red tile roof.',0,130,'2026-01-20T21:41:05.550Z','2026-01-21T20:17:36.644Z','https://upload.wikimedia.org/wikipedia/commons/e/e6/Baden_St_Anna_8431.jpg','Photo by Badener, Wikimedia Commons','The photo shows the side of the St.-Anna-Kapelle in Baden, a building with a red tile roof and a small cross on top, partially obscured by greenery.',NULL,NULL,NULL,NULL,NULL,NULL,'Die St.-Anna-Kapelle ist eine katholische Kapelle in Baden in der Schweiz. Sie befindet sich östlich des Stadtzentrums zwischen Landvogteischloss und Kantonsschule, unweit der Grenze zur Gemeinde Wettingen. Einst diente sie als Gotteshaus des benachbarten Siechenhauses.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (576,'Haus zum Schwert (Baden)',4404677,'Q1590955','de','47.4774000','8.3097200','Baden','AG','Monument',50,'["Bauwerk in Baden AG","Denkmalschutzobjekt im Kanton Aargau","Erbaut im 18. Jahrhundert","Erbaut in den 1790er Jahren","Klassizistisches Bauwerk in der Schweiz","Kulturgut von nationaler Bedeutung im Kanton Aargau"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/5/5f/20120921_Haus_zum_Schwert_von_Oelrainstrasse_aus_2.jpg','Photo by Harubaba, Wikimedia Commons','wikipedia-de','The photo shows the exterior of Haus zum Schwert in Baden, Switzerland, a white building with grey shutters and a decorative balcony.',0,80,'2026-01-20T21:41:16.210Z','2026-01-21T20:17:59.530Z','https://upload.wikimedia.org/wikipedia/commons/4/42/20120921_Haus_zum_Schwert_von_Schwertstrasse_aus.jpg','Photo by Harubaba, Wikimedia Commons','This is a photograph of the Haus zum Schwert in Baden, Switzerland, a three-story building with a red tile roof and grey shutters.',NULL,NULL,NULL,NULL,NULL,NULL,'Das Haus zum Schwert ist ein denkmalgeschütztes Gebäude in Baden in der Schweiz. Es befindet sich nordöstlich des Bahnhofs, in der Nachbarschaft der Reformierten Kirche und des Kursaals. Die Ende des 18.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (577,'Schweizer Kindermuseum',9505514,'Q25388634','de','47.4696700','8.3077700','Baden','AG','Museum',0,'["Kindermuseum in der Schweiz","Museum im Kanton Aargau","Museumsgründung 1985","Organisation (Baden AG)"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/4/48/Kindermuseum_Architektur.jpg','Photo by Richu2014, Wikimedia Commons','wikipedia-de','This is a photograph of the Schweizer Kindermuseum, a large building with a lawn and trees.',0,80,'2026-01-20T21:41:26.097Z','2026-01-21T20:18:44.043Z','https://upload.wikimedia.org/wikipedia/commons/8/83/2024-09-21_Vernissage_Playmobil_Baden_AG_002.jpg','Photo by Ahmet Düz, Wikimedia Commons','This photo shows an outdoor area with large letter signage (KUKA, LITERATUR#) and a small table with items on it, likely near the Schweizer Kindermuseum.','https://upload.wikimedia.org/wikipedia/commons/c/ce/Kindermuseum_Spiel_und_Experimentierstationen.jpg','Photo by Richu2014, Wikimedia Commons','The photo shows children and an adult playing a game inside the Schweizer Kindermuseum, with posters on the wall behind them.',NULL,NULL,NULL,'Das Schweizer Kindermuseum in Baden, Kanton Aargau, thematisiert Kindheit, die Welt des Kindes und ihre Veränderungen durch die vergangenen Jahrhunderte bis in die Gegenwart. Es gründet auf einer umfangreichen Studiensammlung samt Fachbibliothek zu 300 Jahren Kinderkultur.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (578,'Stadtbibliothek Baden',9505528,'Q25162956','de','47.4706500','8.3043600','Baden','AG','Library',0,'["Bibliothek in der Schweiz","Bildung (Kanton Aargau)","Bildungseinrichtungsgründung 1836","Organisation (Baden AG)"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/2/2c/Stadtbibliothek_Baden.jpg','Photo by Frauwalzik, Wikimedia Commons','wikipedia-de','This is a clear, well-lit photo of the Stadtbibliothek Baden, a building with unique architectural features, including a turret and a half-timbered gable.',0,80,'2026-01-20T21:41:39.374Z','2026-01-21T19:44:22.240Z','https://upload.wikimedia.org/wikipedia/commons/7/79/Kl%C3%B6sterli_Baden.jpg','Photo by Wettinger, Wikimedia Commons','The photo shows the exterior of the Stadtbibliothek Baden, a multi-story building with a distinctive architectural style, including a turret and a gabled roof, partially covered in snow.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Stadtbibliothek Baden ist eine Aargauer Gedächtnisinstitution. Sie wurde am 1. Mai 1836 gegründet und zählt damit zu den ältesten Kulturinstitutionen der Stadt Baden.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (579,'Kantonsschule Baden',3631881,'Q1728108','de','47.4706110','8.3129630','Baden','AG',NULL,0,'["Bildungseinrichtungsgründung 1961","Erbaut in den 1960er Jahren","Kantonsschule im Kanton Aargau","Kulturgut von regionaler Bedeutung im Kanton Aargau","Organisation (Baden AG)"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/7/77/Aussicht_Hallerbau.jpg','Photo by Xxxmadmaxxx, Wikimedia Commons','wikipedia-de','This photo shows a cityscape of Baden, Switzerland, featuring a bridge, historic buildings, and a castle on a hill.',0,5,'2026-01-20T21:41:53.984Z','2026-01-21T19:45:01.680Z','https://upload.wikimedia.org/wikipedia/commons/b/ba/BIG_Geb%C3%A4ude.jpg','Photo by Xxxmadmaxxx, Wikimedia Commons','The photo shows the exterior of Kantonsschule Baden, a modern building with large windows and horizontal blinds, surrounded by green grass and trees.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Kantonsschule Baden, auch «Kanti Baden» genannt, ist eine Aargauer Kantonsschule am Stadtrand von Baden. Sie bietet drei Bildungslehrgänge an: das Gymnasium, die Wirtschaftsmittelschule und die Informatikmittelschule. Die Schule ist in zehn modernen Gebäuden untergebracht, die ersten fünf stammen vom Architekt Fritz Haller.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (580,'Sekundarstufenzentrum Burghalde Baden',10655449,'Q60983452','de','47.4716100','8.3025700','Baden','AG',NULL,0,'["Baden AG","Bildung (Kanton Aargau)","Bildungseinrichtung in der Schweiz","Bildungseinrichtungsgründung 1930"]'::jsonb,NULL,NULL,'wikipedia-de',NULL,0,5,'2026-01-20T21:41:54.504Z','2026-01-21T19:45:02.154Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Die Schule Burghalde Baden ist ein Schulzentrum in der Stadt Baden im Schweizer Kanton Aargau. Der Komplex befindet sich auf dem historischen Parkgelände der Villa Burghalde, wobei einzelne Gebäude unter Denkmalschutz stehen. Bis 2018 umfasste er eine Bezirksschule, eine Berufsschule sowie die Musikschule der Region Baden.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (581,'Synagoge (Baden AG)',8541011,'Q14565142','de','47.4786750','8.3088030','Baden','AG','Monument',50,'["Bauwerk in Baden AG","Denkmalschutzobjekt im Kanton Aargau","Erbaut in den 1910er Jahren","Judentum im Kanton Aargau","Kulturgut von nationaler Bedeutung im Kanton Aargau","Kuppelbauwerk","Sakralbau im Kanton Aargau","Synagoge in der Schweiz","Synagogenbau in Europa","Synagogenbau in der Schweiz"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/6/6f/20120923_Synagoge_2_neu.jpg','Photo by Harubaba, Wikimedia Commons','wikipedia-de','This is a photograph of the Synagogue in Baden, Switzerland, featuring its distinctive architecture and Star of David on top.',0,80,'2026-01-20T21:42:08.258Z','2026-01-21T19:45:46.873Z','https://upload.wikimedia.org/wikipedia/commons/0/0f/20120923_Synagoge_1_neu.jpg','Photo by Harubaba, Wikimedia Commons','The photo shows the exterior of the Synagoge in Baden, Switzerland, a yellow building with a distinctive dome and a Star of David on top.',NULL,NULL,NULL,NULL,NULL,NULL,'Die Synagoge in Baden im Kanton Aargau in der Schweiz wurde 1912/13 errichtet. Die Synagoge an der Parkstrasse 17 steht als Kulturgut von nationaler Bedeutung unter Denkmalschutz.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (582,'Aquae Helveticae',4093959,'Q622983','de','47.4790000','8.3097000','Baden','AG','Square',0,'["Archäologischer Fundplatz in Europa","Archäologischer Fundplatz in der Schweiz","Baden AG","Geographie (Kanton Aargau)","Geschichte (Kanton Aargau)","Kulturgut von nationaler Bedeutung im Kanton Aargau","Römischer Vicus","Römisches Bad"]'::jsonb,'https://upload.wikimedia.org/wikipedia/commons/d/d2/Arch%C3%A4ologische_Arbeiten_im_B%C3%A4derviertel.JPG','Photo by Fanimu, Wikimedia Commons','wikipedia-de','The photo shows an archeological dig site with workers excavating stone structures.',0,80,'2026-01-20T21:42:18.659Z','2026-01-21T19:46:01.279Z','https://upload.wikimedia.org/wikipedia/commons/d/d2/Arch%C3%A4ologische_Arbeiten_im_B%C3%A4derviertel.JPG','Photo by Fanimu, Wikimedia Commons','The photo shows an archeological dig site with several people working to excavate ancient stone structures.','https://upload.wikimedia.org/wikipedia/commons/6/66/Wettingen_Isistempel.jpg','Photo by Badener, Wikimedia Commons','The photo shows a stone tablet with Latin inscriptions, likely a historical artifact.',NULL,NULL,NULL,'Aquae Helveticae war eine römische Siedlung (Vicus) auf dem heutigen Stadtgebiet von Baden in der Schweiz. Sie entstand kurz nach der Zeitenwende, als Legionäre des fünf Kilometer entfernten Lagers Vindonissa (heute Windisch) die Thermalquellen am Fluss Limmat zu nutzen begannen und Thermen errichteten. Um die Thermen herum entstand eine Händler- und Handwerkersiedlung, die etwa bis zu Beginn des 5.');
INSERT INTO swiss_landmarks_backup (id,name,wikipedia_page_id,wikidata_qid,lang,latitude,longitude,nearest_city,canton,type,boost_amount,categories,photo_url,photo_attribution,photo_source,photo_description,commons_photo_count,score,created_at,updated_at,photo_url_2,photo_attribution_2,photo_description_2,photo_url_3,photo_attribution_3,photo_description_3,photo_url_4,photo_attribution_4,photo_description_4,wikipedia_extract) VALUES (583,'Swiss Handball Awards',9610055,'Q27975109','de','47.4790387','8.3058038','Baden','AG',NULL,0,'["Ehrung (Handball)","Erstverleihung 2007","Handball (Schweiz)","Liste (Handballspieler)","Liste (ausgezeichnete Sportler)","Sportliche Auszeichnung (Schweiz)"]'::jsonb,NULL,NULL,'wikipedia-de',NULL,0,5,'2026-01-20T21:42:19.254Z','2026-01-21T19:46:03.742Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Die Swiss Handball Awards umfassen verschiedene Auszeichnungen, welche von der Handballzeitschrift handballworld an der Swiss Handball Awards Night für besondere Leistungen vergeben werden.');
